<?php require_once "../config/auth.php";$err="";if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$l=trim($_POST["login"]??"");$p=$_POST["password"]??"";$q=db()->prepare("SELECT * FROM users WHERE username=? OR email=? LIMIT 1");$q->execute([$l,$l]);$u=$q->fetch();if(!$u||!password_verify($p,$u["password_hash"]))$err="Invalid login details.";elseif($u["status"]!=="active")$err="Account blocked.";else{session_regenerate_id(true);$_SESSION["user_id"]=$u["id"];$_SESSION["role"]=$u["role"];header("Location: dashboard.php");exit;}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body class="auth"><form class="box" method="post"><h1>NEXORA <span>SMM</span></h1><h2>Login</h2><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><?php if(isset($_GET["registered"])):?><div class="success">Account created. Please login.</div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input name="login" placeholder="Username or Email" required><input name="password" type="password" placeholder="Password" required><button>Login</button><p>New user? <a href="register.php">Register</a></p></form></body></html>